  'Create an account, open Creator Studio, complete your channel profile, then upload or organize videos from your dashboard.' => 'Erstelle ein Konto, öffne das Creator Studio und vervollständige dein Kanalprofil. Anschließend kannst du über dein Dashboard Videos hochladen und organisieren.',
