  'Creator data' => 'Creator-Daten',
  'Creator profile pages, subscriptions, community posts, comments, and playlists are part of the same account and content system.' => 'Creator-Profile, Abonnements, Communitybeiträge, Kommentare und Playlists gehören zum selben Konto- und Inhaltssystem.',
  'Creator publishing' => 'Inhalte als Creator veröffentlichen',
  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'Ja. Im Creator Studio kannst du zwischen öffentlich, nicht gelistet und privat wählen. Für geplante Videos gilt die gewählte Sichtbarkeit nach der Veröffentlichung.',
  'Creator tools' => 'Creator-Tools',
  'Creator uploads' => 'Uploads von Creatorn',
  'Creators can upload videos, manage visibility, add thumbnails and captions, publish scheduled content, review their library, and track content from Creator Studio.' => 'Im Creator Studio kannst du Videos hochladen, die Sichtbarkeit wählen, Vorschaubilder und Untertitel hinzufügen, Veröffentlichungen planen und deine Bibliothek verwalten.',
  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'Als Creator musst du zutreffende Titel, Beschreibungen, Kategorien, Sprachen, Vorschaubilder, Untertitel sowie Sichtbarkeits- und Zeitplaneinstellungen angeben. Geplante Videos werden erst nach erfolgreicher Verarbeitung und frühestens zum vorgesehenen Zeitpunkt öffentlich.',
  'curl --request GET \\\\ --url' => 'curl --request GET \\\\ --url',
  'Current upload categories' => 'Aktuelle Upload-Kategorien',
  'Data is used to authenticate users, publish and process content, show videos and channels, personalize account preferences, prevent abuse, support moderation, provide admin analytics, and keep creator and viewer features working.' => 'Die Daten werden genutzt, um Nutzer anzumelden, Inhalte zu veröffentlichen und zu verarbeiten, Videos und Kanäle anzuzeigen, Kontoeinstellungen anzupassen, Missbrauch vorzubeugen, die Moderation zu unterstützen, Verwaltungsstatistiken bereitzustellen und Funktionen für Creator und Zuschauer zu betreiben.',
