  'Go to Upload, choose your video file, add required details, select category and language, add a thumbnail, then publish. Large files upload in chunks.' => 'Öffne „Hochladen“, wähle deine Videodatei und ergänze die erforderlichen Angaben, Kategorie, Sprache und ein Vorschaubild. Anschließend kannst du dein Video veröffentlichen. Große Dateien werden in Blöcken übertragen.',
