  'How this PlayHub deployment handles account, content, activity, security, and preference data.' => 'Wie diese PlayHub-Website mit Daten zu deinem Konto, deinen Inhalten, Aktivitäten, Sicherheits- und anderen Einstellungen umgeht.',
