  'If approved, payment is returned through the original method.' => 'Bei Genehmigung wird die Zahlung auf dem ursprünglichen Weg zurückerstattet.',
  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'Ohne eine bezahlte Transaktion beim angebundenen Zahlungsanbieter oder in den Plattformdaten gibt es keine Plattformzahlung, die erstattet werden kann. Erstattungen können nur anhand von Zahlungsbelegen, Abonnement-IDs, Rechnungen oder Transaktionsreferenzen geprüft werden.',
