  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'Das Adminteam hinterlegt die offiziellen Kontaktadressen, Abrechnungskontakte und externen Supportwege für diese Website. Unbestätigte E-Mail-Adressen werden hier nicht angezeigt.',
  'On this page' => 'Auf dieser Seite',
