  'Open settings' => 'Einstellungen öffnen',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'Öffne „Einstellungen“ und dann „Sicherheit“. Dort kannst du dein Passwort und die Zwei-Faktor-Anmeldung verwalten. Je nach Einrichtung erhältst du Bestätigungscodes per E-Mail oder Telefon.',
  'Operational snapshot' => 'Betriebsmomentaufnahme',
