  'Payment help' => 'Zahlungshilfe',
  'Platform' => 'Plattform',
  'Playback' => 'Wiedergabe',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Wiedergabefortschritt, „Später ansehen“-Einträge, Likes, Kommentare, Abonnements, Benachrichtigungen und Verwaltungsstatistiken werden gespeichert, wenn sie zu Funktionen für angemeldete Nutzer gehören.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Über die Navigation und dein Kontomenü findest du Videos, Kommentare, Likes, „Später ansehen“, Abonnements, Benachrichtigungen, Nachrichten, Playlists und Spracheinstellungen.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'Bei PlayHub kannst du mit einem Konto Videos ansehen, hochladen, planen und verwalten sowie Inhalte moderieren.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub bringt Creator, Zuschauer und Communitys zusammen. Teile Videos, entdecke Kanäle und gestalte deine Community mit.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub vereint Creator-Kanäle, Video-Uploads, geplante Veröffentlichungen, Abonnements, Kommentare, Playlists, „Später ansehen“, Livestreamseiten und Verwaltungstools auf einer Plattform.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub nutzt notwendige Cookies und Browserspeicher für Anmeldesitzungen, API-Authentifizierung, CSRF-Schutz und andere Sicherheitsfunktionen, Sprach- und Designauswahl, den Zustand des Kontomenüs und weitere für den Betrieb erforderliche Funktionen.',
  'playhub_language, theme' => 'Playhub_Language, Thema',
  'Popular questions' => 'Beliebte Fragen',
  'Preference storage' => 'Gespeicherte Einstellungen',
  'Privacy Policy' => 'Datenschutzerklärung',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'Datenschutz, Cookies, Kontosicherheit, Supportnachrichten und Moderationsdaten werden über die mit PlayHub verbundenen Richtlinien und Backend-Datensätze verwaltet.',
  'Profile, login, security, and settings help.' => 'Hilfe zu Profil, Anmeldung, Sicherheit und Einstellungen.',
  'Profile, security, and preferences.' => 'Profil, Sicherheit und Präferenzen.',
  'Public API route' => 'Öffentliche API-Route',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'Zu den öffentlichen JSON-Endpunkten gehören /api/health für den Bereitstellungsstatus und /api/upload-options für Upload-Kategorien, Sprachen, Limits, Blockgröße und Trend-Tags.',
