  'Refund and paid feature guidance.' => 'Rückerstattung und Anleitung zu kostenpflichtigen Funktionen.',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'Erstattungen für kostenpflichtige PlayHub-Funktionen richten sich nach den Abrechnungsdaten dieser Website.',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'Die Rückerstattungsabwicklung ist an echte Rechnungsunterlagen und die Überprüfung durch den Administrator gebunden. Wenn die Abrechnung für diese Bereitstellung nicht konfiguriert ist, fällt keine Rückerstattung der Plattformgebühr an.',
  'Refund issued' => 'Rückerstattung ausgestellt',
