  'Select a reason' => 'Grund auswählen',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Wähle eine oder mehrere Videodateien aus und ergänze die erforderlichen Angaben. Lege Kategorie, Sprache, Vorschaubild und Sichtbarkeit fest und veröffentliche dein Video. Große Dateien werden in Teilen hochgeladen, bevor die Verarbeitung beginnt.',
  'Send a message and it will be saved for admins.' => 'Sende eine Nachricht an das Adminteam.',
  'Send billing details to admin support for review.' => 'Sende die Rechnungsdaten zur Prüfung an den Support.',
  'Send message' => 'Nachricht senden',
  'Send order details through the refund popup.' => 'Gib die Bestelldaten im Erstattungsformular an.',
  'Send us a message' => 'Schreib uns eine Nachricht',
