  'Settings and login' => 'Einstellungen und Login',
  'Short summary' => 'Kurze Zusammenfassung',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Melde dich an und öffne die Einstellungen, um dein Konto, Profil, Passwort, Benachrichtigungen, Datenschutz und Creator-Einstellungen zu verwalten. Wenn du Hilfe beim Hochladen oder mit deinen Inhalten brauchst, nenne den Videotitel, deinen Kanal, deinen Browser und die angezeigte Fehlermeldung.',
  'Sign in for account support' => 'Für Kontohilfe anmelden',
  'Signed in' => 'Angemeldet',
  'Start uploading' => 'Upload starten',
  'Still can’t find an answer?' => 'Du hast noch keine Antwort gefunden?',
  'Stored for admins' => 'Für Administratoren gespeichert',
  'Stores language, theme, and interface preferences.' => 'Speichert Sprach-, Design- und Benutzeroberflächeneinstellungen.',
  'Studio, playlists, analytics, channels.' => 'Studio, Playlists, Analysen, Kanäle.',
  'Submit a billing or refund message to admin support.' => 'Sende deine Frage zur Rechnung oder Erstattung an den Support.',
  'Submit refund request' => 'Erstattung anfragen',
  'Submit request' => 'Anfrage abschicken',
  'Subscription cancellation' => 'Kündigung des Abonnements',
  'Support dashboard' => 'Support-Dashboard',
  'System status' => 'Systemstatus',
  'Table' => 'Tisch',
  'Taxonomies' => 'Taxonomien',
  'Technical issue' => 'Technisches Problem',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Technische Hinweise für deine Integration mit der PlayHub-API und dem Uploadablauf.',
  'Tell us more about your question or request...' => 'Beschreibe deine Frage oder dein Anliegen …',
  'Terms of Use' => 'Nutzungsbedingungen',
  'The configured' => 'Die konfigurierte',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Die Entwicklerseite ist mit dem Live-Laravel-Backend verbunden: Routeninventar, Datenbankanzahl, Upload-Limits und Plattformmetadaten werden von /api/developers geladen.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Die Oberfläche speichert deine Sprache, dein Design, die Wiedergabewarteschlange, deinen Wiedergabefortschritt und den Zustand der Oberfläche. So bleiben diese Einstellungen beim Seitenwechsel und Neuladen erhalten.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Der Verarbeitungsauftrag kodiert Wiedergaben, erstellt bei Bedarf Miniaturansichten, speichert Untertitel und markiert Videos als bereit, wenn die Verarbeitung abgeschlossen ist. Zukünftig geplante Videos bleiben privat, bis der Planer sie freigibt.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Das Upload-System ist datenbankgestützt, unterstützt Kategorien und Sprachen über die API, verarbeitet hochgeladene Videos, speichert Miniaturansichten und Untertitel und hält geplante Inhalte bis zu ihrer Veröffentlichung privat.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Auf dieser Seite wird erläutert, wie PlayHub Cookies und Browserspeicher für Sitzungen, Sicherheit, Einstellungen, Wiedergabe und authentifizierte Funktionen verwendet.',
  'Ticket source' => 'Ticketquelle',
  'Top content categories' => 'Top-Inhaltskategorien',
  'Topic' => 'Thema',
  'Transaction / invoice' => 'Transaktion/Rechnung',
  'Transaction / invoice ID' => 'Transaktions-/Rechnungs-ID',
  'Unable to send message.' => 'Nachricht kann nicht gesendet werden.',
  'Unable to submit refund request.' => 'Rückerstattungsantrag kann nicht eingereicht werden.',
  'Understanding admin support tickets' => 'Administrator-Support-Tickets verstehen',
  'Upload and processing help' => 'Hilfe beim Hochladen und Verarbeiten',
  'Upload chunks' => 'Chunks hochladen',
  'Upload issues' => 'Probleme beim Hochladen',
  'Upload languages' => 'Sprachen hochladen',
  'Upload limit' => 'Upload-Limit',
  'Upload options' => 'Upload-Optionen',
  'Upload or processing' => 'Hochladen oder Verarbeiten',
  'Upload page' => 'Seite hochladen',
  'Upload pipeline' => 'Pipeline hochladen',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Mit Live-PlayHub-Daten hochladen, ansehen, abonnieren, moderieren und erstellen.',
  'Uploaded videos' => 'Hochgeladene Videos',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Nach dem Hochladen werden abspielbare Versionen deines Videos erstellt. Wie lange das dauert, hängt von Dateigröße, Videolänge, Serverauslastung und Warteschlange ab. Den aktuellen Status siehst du auf der Uploadseite und im Creator Studio.',
  'Uploads, scheduling, and processing are available.' => 'Uploads, Planung und Verarbeitung sind verfügbar.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Nutze /api/videos, die Kanal-Endpunkte und authentifizierte Routen für Creator-Abläufe.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Melde Videos und Kommentare direkt am Inhalt, damit das Adminteam den richtigen Verweis erhält. In der Verwaltung findest du Nutzer, Inhalte, Meldungen, Monetarisierung, Statistiken, Support, Rollen und Systemeinstellungen.',
  'Use Contact Us' => 'Kontaktformular öffnen',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Nutze JSON für gewöhnliche API-Anfragen und FormData für Datei-Uploads. Beachte die Validierung: Kategorien und Sprachen verwenden die konfigurierten IDs. Als Sichtbarkeit sind public, unlisted und private erlaubt. Untertitel kannst du als SRT-, VTT- oder TXT-Datei übergeben.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'In den Einstellungen verwaltest du dein Profil, deine Sicherheit, dein Passwort, Bestätigungscodes, Geräte und Benachrichtigungen. Wenn du dich nicht anmelden kannst, nutze die Hilfe beim Anmelden und nenne dem Adminteam die E-Mail-Adresse deines Kontos.',
  'Use the contact form' => 'Kontaktformular nutzen',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Melde Videos, Kommentare und Community-Beiträge über die jeweilige Meldefunktion. So kann das Adminteam den betroffenen Inhalt direkt prüfen.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Wenn ein Video, Kommentar oder Communitybeitrag gegen die Regeln verstoßen könnte, nutze die Meldefunktion direkt am Inhalt. So kann das Adminteam genau den betroffenen Inhalt prüfen.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Hier findest du Hilfe zu deinem Konto, technischen Problemen, Meldungen und Fragen an das Adminteam.',
  'Video categories' => 'Videokategorien',
  'Video for everyone. Built for creators and viewers.' => 'Video für alle. Basierend auf echten Plattformdaten.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Probleme beim Hochladen, Planen, Miniaturansichten und der Verarbeitung von Videos.',
  'Videos, thumbnails, captions, processing.' => 'Videos, Miniaturansichten, Bildunterschriften, Bearbeitung.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Stöbere durch Kategorien, suche nach Videos und abonniere deine Lieblingskanäle. Speichere Videos für später, schreib Kommentare und erhalte Benachrichtigungen. Sprache und Barrierefreiheit kannst du in deinen Einstellungen anpassen.',
  'Viewing and community help' => 'Hilfe zum Anschauen und zur Community',
  'Waiting for backend endpoint inventory.' => 'Warten auf die Bestandsaufnahme des Backend-Endpunkts.',
  'We’re here to help.' => 'Wir sind hier, um zu helfen.',
  'What is PlayHub?' => 'Was ist PlayHub?',
  'What PlayHub does' => 'Was du mit PlayHub machen kannst',
  'Where do contact messages go?' => 'Wohin gehen Kontaktnachrichten?',
  'Why is my video still processing?' => 'Warum wird mein Video noch verarbeitet?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Ja. Lege beim Hochladen Datum und Uhrzeit fest. Dein Video wird verarbeitet und bleibt bis zum geplanten Zeitpunkt privat. Danach gibt es der nächste Durchlauf der Zeitplanverarbeitung frei.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Ja. Lege auf der Upload-Seite den gewünschten Zeitpunkt fest. Dein Video wird nach der Verarbeitung zum geplanten Zeitpunkt veröffentlicht.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Du bist als Gast unterwegs. Melde dich an, um deine Kontofunktionen zu nutzen.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Du bist für deine Zugangsdaten, Profilaktivitäten, Uploads, Kommentare, Nachrichten und alle Creator- oder Verwaltungsaktionen über dein Konto verantwortlich. Nutze sichere Passwörter und halte die Zustellwege für deine Bestätigungscodes aktuell.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Du kannst Cookies und lokale Daten in deinen Browsereinstellungen löschen. Wenn du notwendige Daten löschst, kannst du abgemeldet werden. Dabei können auch Sprach- und Designeinstellungen sowie der lokale Wiedergabestatus zurückgesetzt werden. Gegebenenfalls musst du dich danach erneut anmelden.',
  'You receive a response by email.' => 'Du erhältst eine Antwort per E-Mail.',
  'You’re in control' => 'Du hast die Kontrolle',
  'Your choices' => 'Deine Wahl',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Deine Nachricht wird gespeichert und erreicht das Adminteam im Supportbereich.',
