  'Publish consistently' => 'Konsistent veröffentlichen',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'Lade dein erstes Video hoch und zeig deinen Zuschauern, warum sich ein Abo lohnt.',
  'Use Shorts for discovery' => 'Mit Shorts neue Zuschauer erreichen',
  'Keep testing quick hooks and link viewers to longer videos.' => 'Teste kurze, spannende Einstiege und verlinke auf deine längeren Videos.',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'Erstelle kurze Videos im Hochformat, um neue Zuschauer auf deinen Kanal aufmerksam zu machen.',
  'Create short' => 'Short erstellen',
  'Turn comments into loyalty' => 'Über Kommentare mit deinem Publikum verbinden',
  'Reply to recent comments and turn viewers into returning fans.' => 'Antworte auf neue Kommentare und bleib mit deinem Publikum im Gespräch.',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'Stell in deinem nächsten Video eine Frage und antworte zeitnah auf Kommentare.',
  'View comments' => 'Kommentare anzeigen',
  'Improve public reach' => 'Öffentliche Reichweite verbessern',
  'Keep strong videos visible and refresh weak titles.' => 'Starke Videos sichtbar halten und schwache Titel aktualisieren.',
