  'Channel profile' => 'Kanalprofil',
  'Update your bio, channel details, and public creator presence.' => 'Aktualisiere deine Biografie, Kanalangaben und dein öffentliches Creator-Profil.',
  'Audience building' => 'Publikumsaufbau',
  'Study subscribers, comments, and what viewers respond to most.' => 'Sieh dir an, wie sich deine Abonnements entwickeln und welche Inhalte dein Publikum besonders ansprechen.',
  'Top content to learn from' => 'Top-Inhalte zum Lernen',
  'Upload videos to unlock performance lessons.' => 'Lade Videos hoch, um Tipps auf Grundlage deiner Statistiken zu erhalten.',
  'Tips to reach more viewers' => 'Tipps, um mehr Zuschauer zu erreichen',
  'Creator checklist' => 'Checkliste für Creator',
  'Hook viewers in the first 3 seconds' => 'Wecke in den ersten 3 Sekunden Interesse',
  'Open with the result, conflict, or visual payoff before adding context.' => 'Zeig zuerst das Ergebnis, die spannende Frage oder einen starken Bildmoment. Erkläre danach den Hintergrund.',
  'Make titles searchable' => 'Titel durchsuchbar machen',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'Nutze Begriffe, nach denen dein Publikum sucht, und halte im Video, was dein Titel verspricht.',
  'Convert shorts into sessions' => 'Kurzfilme in Sitzungen umwandeln',
  'Pin a comment or description link from each short to a related full video.' => 'Einen Kommentar- oder Beschreibungslink von jedem Kurzfilm an ein zugehöriges vollständiges Video anheften.',
  'Refresh underperforming uploads' => 'Videos mit geringer Reichweite überarbeiten',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'Überarbeite Titel und Vorschaubilder, sobald du genügend Impressionen für einen Vergleich hast.',
  'Upload source' => 'Quelle hochladen',
  'Choose a local video file or import a public video from an enabled provider.' => 'Wähle eine Videodatei aus oder importiere ein öffentliches Video von einem verfügbaren Anbieter.',
