  'Enter the 6-digit code sent to your phone.' => 'Gib den sechsstelligen Code ein, den du per SMS erhalten hast.',
  'Enter the 6-digit code sent to your email.' => 'Gib den sechsstelligen Code ein, den du per E-Mail erhalten hast.',
  'Enter the 6-digit code from your phone to disable two-factor authentication.' => 'Gib den sechsstelligen Code aus deiner SMS ein, um die Zwei-Faktor-Authentifizierung zu deaktivieren.',
  'Enter the 6-digit code from your email to disable two-factor authentication.' => 'Gib den sechsstelligen Code aus deiner E-Mail ein, um die Zwei-Faktor-Authentifizierung zu deaktivieren.',
  'Find out how we handle your data in our privacy policy.' => 'Wie wir mit deinen Daten umgehen, erfährst du in unserer Datenschutzerklärung.',
  'This email was sent by {site}.' => 'Diese E-Mail wurde von {site} gesendet.',
  'Notification' => 'Benachrichtigung',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.\\n\\nThe upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Entdecke Kanäle, lade Videos hoch und plane ihre Veröffentlichung. Abonniere Creator, kommentiere Videos und sammle deine Favoriten in Playlists oder unter „Später ansehen“. Livestreams und Verwaltungsfunktionen gehören ebenfalls dazu.

Beim Hochladen kannst du aus den verfügbaren Kategorien und Sprachen wählen. PlayHub verarbeitet deine Videos und speichert Vorschaubilder und Untertitel. Geplante Videos bleiben bis zu ihrer Veröffentlichung privat.',
  'Creators can upload videos, manage visibility, add thumbnails and captions, publish scheduled content, review their library, and track content from Creator Studio.\\n\\nCreator profile pages, subscriptions, community posts, comments, and playlists are part of the same account and content system.' => 'Im Creator Studio lädst du Videos hoch, legst ihre Sichtbarkeit fest und ergänzt Vorschaubilder und Untertitel. Plane Veröffentlichungen, verwalte deine Mediathek und behalte deine Inhalte im Blick.

Dein Konto verbindet deinen Kanal, Abonnements, Communitybeiträge, Kommentare und Playlists.',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.\\n\\nAuthenticated APIs use the existing Laravel Sanctum token flow. Account, upload, creator, playlist, notification, comment, like, subscription, and admin endpoints are served under /api.' => 'Öffentliche JSON-Endpunkte sind etwa /api/health für den Plattformstatus und /api/upload-options für Kategorien, Sprachen, Limits, Teilgrößen und angesagte Tags.

Geschützte APIs nutzen den vorhandenen Tokenablauf von Laravel Sanctum. Endpunkte für Konten, Uploads, Creator, Playlists, Benachrichtigungen, Kommentare, Likes, Abonnements und Verwaltung liegen unter /api.',
  'Large uploads use upload sessions: create a session, send numbered chunks, then complete the session with title, description, category, language, visibility, schedule, thumbnail, captions, and monetization fields.\\n\\nThe processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Für große Uploads erstellst du eine Uploadsitzung, überträgst nummerierte Teile und schließt die Sitzung mit den Videodetails ab: Titel, Beschreibung, Kategorie, Sprache, Sichtbarkeit, Zeitplan, Vorschaubild, Untertitel und Monetarisierung.

Anschließend erstellt die Verarbeitung die Videoauflösungen und bei Bedarf Vorschaubilder, speichert Untertitel und markiert das Video als bereit. Geplante Videos bleiben bis zur Freigabe durch den Scheduler privat.',
  'If paid creator features or a Pro plan are enabled for this deployment, refund requests should include the account email, transaction ID, subscription ID, payment date, and reason for the request. Administrators should verify the request against payment-provider records before issuing any refund.' => 'Wenn diese Website kostenpflichtige Creator-Funktionen oder einen Pro-Tarif anbietet, gib bei einer Erstattungsanfrage die E-Mail-Adresse deines Kontos, Transaktions-ID, Abonnement-ID, Zahlungsdatum und den Grund an. Das Adminteam sollte die Anfrage vor einer Erstattung mit den Daten des Zahlungsanbieters abgleichen.',
  'PlayHub cannot refund third-party bank fees, chargeback fees, external service fees, or payments made outside the configured platform billing flow. Content removals or account restrictions do not automatically create a refund unless required by law or the active billing terms.' => 'PlayHub kann keine Bankgebühren Dritter, Rückbuchungsgebühren, externen Servicegebühren oder Zahlungen außerhalb der eingerichteten Plattformabrechnung erstatten. Das Entfernen von Inhalten oder Einschränken eines Kontos führt nicht automatisch zu einer Erstattung, sofern Gesetz oder geltende Abrechnungsbedingungen dies nicht vorsehen.',
  'PlayHub stores account details, creator profile data, uploaded videos, thumbnails, captions, categories, languages, playlists, comments, likes, subscriptions, watch-later records, notifications, messages, reports, device/session data, language preference, theme preference, and security settings needed to operate the platform.' => 'PlayHub speichert die für den Betrieb erforderlichen Kontodaten, Creator-Profile, hochgeladenen Videos, Vorschaubilder, Untertitel, Kategorien, Sprachen, Playlists, Kommentare, Likes, Abonnements, „Später ansehen“-Einträge, Benachrichtigungen, Nachrichten, Meldungen, Geräte- und Sitzungsdaten sowie Sprach-, Design- und Sicherheitseinstellungen.',
  'Users can update profile and preference data in Settings, manage uploaded content in Creator Studio, change password and two-factor options in Security settings, and use report tools for content safety. Administrators can manage users, content, reports, roles, and system settings from the admin dashboard.' => 'In den Einstellungen kannst du dein Profil und deine Präferenzen aktualisieren. Deine Uploads verwaltest du im Creator Studio. Unter Sicherheit kannst du dein Passwort und die Zwei-Faktor-Authentifizierung ändern. Inhalte kannst du über die Meldefunktionen melden. Das Adminteam verwaltet Nutzer, Inhalte, Meldungen, Rollen und Systemeinstellungen über die Verwaltung.',
  'Uploaded media and account records are retained while needed for platform operation, legal compliance, security, moderation, and user-requested features. Deleting users or content should also remove associated server media files where implemented by the admin tools.' => 'Hochgeladene Medien und Kontodaten werden so lange gespeichert, wie sie für den Plattformbetrieb, gesetzliche Pflichten, Sicherheit, Moderation und von dir angeforderte Funktionen benötigt werden. Beim Löschen von Nutzern oder Inhalten sollten auch zugehörige Mediendateien auf dem Server entfernt werden, soweit die Verwaltungsfunktionen dies umsetzen.',
  'Terms of Service' => 'Nutzungsbedingungen',
  'Do not upload content you do not have rights to publish. Do not post illegal, abusive, harmful, deceptive, spam, malware, harassment, or privacy-violating content. PlayHub administrators may restrict, remove, suspend, verify, or delete users and content according to platform rules and applicable law.' => 'Lade nur Inhalte hoch, die du veröffentlichen darfst. Veröffentliche keine rechtswidrigen, beleidigenden, schädlichen oder täuschenden Inhalte, Spam oder Schadsoftware. Belästige niemanden und verletze keine Privatsphäre. Das Adminteam kann Nutzer und Inhalte entsprechend den Plattformregeln und geltendem Recht einschränken, entfernen, sperren, verifizieren oder löschen.',
  'PlayHub may process uploads, create video renditions, generate thumbnails, store metadata, collect engagement activity, and provide analytics. Availability can depend on server queues, storage, media processing, network conditions, and administrator configuration.' => 'PlayHub kann Uploads verarbeiten, Videoversionen und Vorschaubilder erstellen, Metadaten speichern, Interaktionen erfassen und Statistiken bereitstellen. Die Verfügbarkeit kann von Warteschlangen, Speicher, Medienverarbeitung, Netzwerk und den Einstellungen des Adminteams abhängen.',
  'Watch, create and connect with your community on {site}.' => 'Schau Videos, werde kreativ und triff deine Community auf {site}.',
  'Subscribe for {price} per month' => 'Für {price} im Monat abonnieren',
