  'Import an AUF1 video page. Uses the published original stream when available, with the official player as fallback.' => 'Füge den Link zu einem AUF1-Video ein. Wenn verfügbar, wird der veröffentlichte Originalstream genutzt. Der offizielle Player steht als Mirror bereit.',
  'Use an AUF1 video page URL, not a channel, search, news post, radio, or live URL.' => 'Füge den Link zu einem aufgezeichneten AUF1-Video ein. Links zu Kanälen, Suchergebnissen, Textmeldungen, Radio oder Livestreams werden noch nicht unterstützt.',
  'AUF1 video metadata is currently unavailable. Try again later.' => 'Die AUF1-Videodetails sind gerade nicht verfügbar. Versuch es später erneut.',
  'AUF1 video metadata could not be verified. Use an available recorded video page.' => 'Die AUF1-Videodetails konnten nicht geprüft werden. Verwende den Link zu einem verfügbaren aufgezeichneten Video.',
  'AUF1 video playback is currently unavailable. Try again later.' => 'Das AUF1-Video lässt sich gerade nicht abspielen. Versuch es später erneut.',
  'Subtitles' => 'Untertitel',
  'Remove post' => 'Beitrag entfernen',
  'Remove community post?' => 'Communitybeitrag entfernen?',
  'This post will be removed from its community. This cannot be undone.' => 'Der Beitrag wird aus der Community entfernt. Das kannst du nicht rückgängig machen.',
  'External media services' => 'Externe Mediendienste',
  'Manage image hosters, private Oracle staging and Odysee publishing in one place.' => 'Verwalte Bildhoster, den privaten Oracle-Zwischenspeicher und die Veröffentlichung auf Odysee an einem Ort.',
  'No account key is needed. {platform} uses the public upload form.' => 'Du brauchst keinen Kontoschlüssel. {platform} nutzt das öffentliche Uploadformular.',
  'Image links are public outside {platform}. A connection test uploads a small synthetic image.' => 'Die Bildlinks sind außerhalb von {platform} öffentlich erreichbar. Beim Verbindungstest wird ein kleines, künstlich erzeugtes Testbild hochgeladen.',
  'Use your own Fastpic API token. If your account does not have API access, keep this provider disabled.' => 'Verwende deinen eigenen Fastpic-API-Token. Wenn dein Konto keinen API-Zugang hat, lass diesen Anbieter deaktiviert.',
  'Use your own Postimages API key. Keep the public client compatibility values unless the provider changes them.' => 'Verwende deinen eigenen Postimages-API-Schlüssel. Behalte die öffentlichen Kompatibilitätswerte bei, solange der Anbieter sie nicht ändert.',
  'Create a private Standard bucket in your Oracle home region.' => 'Erstelle einen privaten Standard-Bucket in deiner Oracle-Heimatregion.',
  'Copy its region, namespace and bucket name from Object Storage.' => 'Übernimm Region, Namespace und Bucketnamen aus Object Storage.',
  'In your Oracle profile, open Tokens and keys → Customer secret keys. Enter the access key and its one-time secret here. Use customer secret keys, not an API signing key.' => 'Öffne in deinem Oracle-Profil „Token und Schlüssel → Kunden-Secret Keys“. Trage hier den Zugriffsschlüssel und den einmalig angezeigten Secret Key ein. Du brauchst Kunden-Secret Keys, keinen API-Signaturschlüssel.',
  'Save the connection, then check bucket access. This test does not upload a video.' => 'Speichere die Verbindung und prüfe danach den Bucketzugriff. Bei diesem Test wird kein Video hochgeladen.',
  'Create an Odysee account and a channel for {platform} clips.' => 'Erstelle ein Odysee-Konto und einen Kanal für die Clips von {platform}.',
  'Sign in below, choose your channel and save the connection. You do not need to find an API key.' => 'Melde dich unten an, wähle deinen Kanal und speichere die Verbindung. Du musst keinen API-Schlüssel suchen.',
  'Unlisted videos remain accessible to anyone with their link. {platform} access restrictions do not protect that external link.' => 'Nicht gelistete Videos bleiben für alle erreichbar, die ihren Link kennen. Die Zugriffsregeln von {platform} schützen diesen externen Link nicht.',
