  'Open API & ShareX, sign in and confirm your email address. Create a separate API key for {platform} and copy the key when it is shown.' => 'Öffne „API & ShareX“, melde dich an und bestätige deine E-Mail-Adresse. Erstelle einen eigenen API-Schlüssel für {platform} und kopiere ihn, sobald er angezeigt wird.',
  'Paste that key into API Key, save the connection and upload a test image.' => 'Füge den Schlüssel unter „API-Schlüssel“ ein, speichere die Verbindung und lade ein Testbild hoch.',
  'Open the API access page, sign in and copy your personal API key. Paste it into API Key below.' => 'Öffne den API-Zugang, melde dich an und kopiere deinen persönlichen API-Schlüssel. Füge ihn unten unter „API-Schlüssel“ ein.',
  'The O and M values are public compatibility defaults, not your account key. Change them only when the provider tells you to.' => 'O und M sind öffentliche Vorgabewerte für die Kompatibilität. Dein Kontoschlüssel gehört dort nicht hinein. Ändere sie nur, wenn der Anbieter dazu auffordert.',
  'Open Oracle buckets and choose your home region and compartment. Create a private Standard bucket or open your existing one.' => 'Öffne „Oracle-Buckets“ und wähle deine Heimatregion und dein Compartment. Erstelle einen privaten Standard-Bucket oder öffne deinen vorhandenen Bucket.',
  'Copy the selected region into Region, the Object Storage namespace from the bucket details into Namespace, and the bucket name into Bucket.' => 'Trage die ausgewählte Region unter „Region“ ein. Übernimm den Object-Storage-Namespace aus den Bucketdetails unter „Namespace“ und den Bucketnamen unter „Bucket“.',
  'Open Oracle customer secret keys. Under Tokens and keys → Customer secret keys, generate a new pair. Copy its access key into Access Key and the secret shown once into Secret Key. API signing keys and auth tokens are different credentials.' => 'Öffne „Oracle-Kunden-Secret-Keys“. Erstelle unter „Token und Schlüssel → Kunden-Secret Keys“ ein neues Paar. Kopiere den Zugriffsschlüssel nach „Zugriffsschlüssel“ und den einmalig angezeigten geheimen Schlüssel nach „Secret Key“. API-Signaturschlüssel und Authentifizierungstoken sind andere Zugangsdaten.',
  'Keep the saved secret' => 'Gespeicherten Schlüssel behalten',
  'Remove the saved secret when settings are saved' => 'Gespeicherten Schlüssel beim Speichern entfernen',
  'Fastpic accepted the test image but only permits thumbnail links for it. Original-size images cannot be used this way.' => 'Fastpic hat das Testbild angenommen, gibt dafür aber nur Vorschaulinks frei. Originalbilder können so nicht verwendet werden.',
  'Your clip uploads' => 'Deine Clip-Uploads',
